sed -i '' "s/^  viewer:     { view: true,  edit: false },/&\n  support:    { view: true,  edit: false },/" src/permissions.js && cat >> test/permissions.test.js <<'EOF'
test('support can view but not edit', () => { assert.ok(canView('support')); assert.ok(!canEdit('support')); });
test('support can list and read invoices but not update or delete', () => {
  const inv = require('../src/invoices'); const user = { role: 'support' };
  assert.strictEqual(inv.listInvoices(user).length, 2);
  assert.strictEqual(inv.getInvoice(user, 'inv-1').id, 'inv-1');
  assert.throws(() => inv.updateInvoice(user, 'inv-1', { amount: 0 }), /forbidden/);
  assert.throws(() => inv.deleteInvoice(user, 'inv-1'), /forbidden/);
  assert.strictEqual(inv.getInvoice(user, 'inv-1').amount, 120);
});
EOF
cat src/permissions.js; npm test 2>&1 | tail -12

